// NOTE FOR THE READER: this is the pathway's start node. It runs before any
// conversation turn, fetches the dealer's configuration, and publishes the
// variable bag every other node reads. The guiding rule throughout: compute
// in code what a model could get wrong at runtime (timezones, day-of-week
// resolution, config key variants), and hand the model finished values.
// Hosts and keys below are sanitized placeholders.
// The single switch for the whole Middleware pathway. It gates this node's own
// `debug` object and rides downstream as the `debug_enabled` call variable every
// other snippet in the pathway reads. Flipping it takes a snippet push and a new
// pathway version: the pinned snippet is what runs, so editing this file alone
// changes nothing until a pathway version pins the push.
const DEBUG_ENABLED = true;

// ---------------------------------------------------------------------------
// Debug
//
// `debug` carries the payload this node was handed, the config it resolved from
// it, and every outbound call as a request-and-response pair. It is switched on
// by the DEBUG_ENABLED constant above - this node owns that flag for the whole
// pathway and re-exports it as the `debug_enabled` variable the downstream
// snippets read. Off means the whole `debug` key disappears and no call
// recording happens at all.
//
// Secrets are reduced to presence and length. Nothing here carries a byte of a
// token, an API key or an Authorization header.
// ---------------------------------------------------------------------------

// Caps request/response bodies and long payload values in the debug log. A
// services_config, or an appointment list, would otherwise crowd out everything
// else in the call log.
const DEBUG_BODY_MAX_CHARS = 1000;

// Presence and length, and nothing else. Enough to tell a missing credential
// from an unsubstituted {{...}} from a real one the API still rejected, without
// putting any part of the value in the call log.
function fingerprintKey(value) {
	const s = value === null || value === undefined ? '' : String(value);
	if (s === '') return { present: false };
	return {
		present: true,
		length: s.length,
		has_surrounding_whitespace: s !== s.trim(),
		looks_unsubstituted: s.includes('{{')
	};
}

// Response bodies stay raw: a truncated string still shows an HTML error page or
// a malformed payload, which a failed JSON.parse would have thrown away.
function debugBody(raw) {
	if (raw === undefined || raw === null) return null;
	const s = String(raw);
	return s.length > DEBUG_BODY_MAX_CHARS
		? `${s.slice(0, DEBUG_BODY_MAX_CHARS)}...[truncated, ${s.length} chars total]`
		: s;
}

// Matched on the header NAME rather than against a list of known ones, so a
// credential header added later is redacted by default instead of leaking until
// someone remembers to add it here.
function isSecretName(name) {
	return /authorization|api[-_ ]?key|token|secret|password|cookie/i.test(String(name));
}

function maskHeaders(headers) {
	const out = {};
	for (const [name, value] of Object.entries(headers || {})) {
		out[name] = isSecretName(name)
			? fingerprintKey(String(value).replace(/^Bearer\s+/i, ''))
			: value;
	}
	return out;
}

// content-type proves we reached the API and not a proxy error page, and the
// trace ids let the other side find this exact request.
function pickHeaders(res) {
	const keep = [
		'content-type', 'allow', 'server', 'retry-after',
		'x-request-id', 'x-correlation-id', 'cf-ray', 'www-authenticate'
	];
	const out = {};
	for (const name of keep) {
		const value = res?.headers?.get?.(name);
		if (value !== null && value !== undefined) out[name] = value;
	}
	return out;
}

// The same rule as maskHeaders, applied to payload keys. `secrets` is a whole
// sub-object of credentials, so every value in it is fingerprinted.
function redactPayload(json) {
	if (!json || typeof json !== 'object') return json ?? null;
	const out = {};
	for (const [key, value] of Object.entries(json)) {
		if (key === 'secrets' && value && typeof value === 'object') {
			out.secrets = Object.fromEntries(Object.entries(value).map(([k, v]) => [k, fingerprintKey(v)]));
		} else if (isSecretName(key)) {
			out[key] = fingerprintKey(value);
		} else {
			out[key] = typeof value === 'string' ? debugBody(value) : value;
		}
	}
	return out;
}

function nodeRequest(json) {
	return {
		payload_keys: Object.keys(json || {}).sort().join(', '),
		payload: redactPayload(json)
	};
}

// One record per outbound call. The record is pushed BEFORE the await and
// completed after, so a call that timed out or threw stays in the log instead of
// vanishing - which is the case where the log matters most.
//
// `Array.isArray(httpLog)` rather than truthiness: a null log allocates nothing
// and records nothing.
function startCall(httpLog, target, method, url, headers, body) {
	if (!Array.isArray(httpLog)) return null;
	const record = {
		target,
		method,
		url,
		request_headers: maskHeaders(headers),
		request_body: debugBody(
			body === undefined || body === null ? null : typeof body === 'string' ? body : JSON.stringify(body)
		)
	};
	httpLog.push(record);
	return record;
}

function finishCall(record, startedAt, res, text) {
	if (!record) return;
	record.ms = Date.now() - startedAt;
	record.status = res?.status ?? 0;
	record.ok = record.status >= 200 && record.status < 300;
	record.response_headers = pickHeaders(res);
	record.response_body = debugBody(text);
}

function failCall(record, startedAt, error, aborted) {
	if (!record) return;
	record.ms = Date.now() - startedAt;
	record.status = 0;
	record.ok = false;
	record.error =
		aborted || error?.name === 'AbortError'
			? 'timeout'
			: `network error: ${error?.message || String(error)}`;
}

// ----- TICKET-66: deterministic spoken hours ------------------------------
// The agent misreads raw hours JSON on the phone: the Aug-04 audit found it
// quoting a neighbouring day's row and claiming "closed" for days the config
// says are open. All day arithmetic therefore happens HERE, and the agent only
// ever reads finished, day-labeled sentences. Handles both config schemas —
// {weekday, saturday, sunday} and per-day {mon..sun / monday..sunday}. A shape
// this code doesn't recognize renders as '' (or a day goes unlisted), and the
// prompt's no-data rule takes over: never guess, offer the service line.

const HOURS_DAY_LABELS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const HOURS_DAY_KEYS = [
	['sun', 'sunday'],
	['mon', 'monday'],
	['tue', 'tues', 'tuesday'],
	['wed', 'wednesday'],
	['thu', 'thur', 'thurs', 'thursday'],
	['fri', 'friday'],
	['sat', 'saturday']
];

function hoursSpokenClock(hhmm) {
	const m = /^(\d{1,2}):(\d{2})$/.exec(String(hhmm || '').trim());
	if (!m) return '';
	let h = Number(m[1]);
	const min = m[2];
	const ampm = h >= 12 ? 'PM' : 'AM';
	h = h % 12 || 12;
	return min === '00' ? `${h} ${ampm}` : `${h}:${min} ${ampm}`;
}

// "07:00-18:00" -> "7 AM to 6 PM"; "closed" -> "closed"; anything else -> ''.
function hoursSpokenRange(value) {
	const raw = String(value || '').trim().toLowerCase();
	if (!raw) return '';
	if (raw === 'closed') return 'closed';
	const m = /^(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})$/.exec(raw);
	if (!m) return '';
	const open = hoursSpokenClock(m[1]);
	const close = hoursSpokenClock(m[2]);
	return open && close ? `${open} to ${close}` : '';
}

// dayIndex 0=Sunday..6=Saturday. '' when the config doesn't cover that day —
// a miss is reported as a miss, never bridged from another day.
function hoursRangeForDay(hoursObj, dayIndex) {
	if (!hoursObj || typeof hoursObj !== 'object') return '';
	const lower = {};
	for (const [k, v] of Object.entries(hoursObj)) {
		lower[String(k).toLowerCase().trim()] = v;
	}
	for (const key of HOURS_DAY_KEYS[dayIndex]) {
		if (lower[key] !== undefined) return hoursSpokenRange(lower[key]);
	}
	if (dayIndex >= 1 && dayIndex <= 5 && lower.weekday !== undefined) {
		return hoursSpokenRange(lower.weekday);
	}
	return '';
}

// One subject's week, every day named explicitly, Monday first:
// "Service department: Monday 7 AM to 6 PM; ... Sunday closed."
function hoursWeekLine(label, hoursObj) {
	const parts = [];
	for (let i = 1; i <= 7; i++) {
		const dayIndex = i % 7;
		const range = hoursRangeForDay(hoursObj, dayIndex);
		if (range) parts.push(`${HOURS_DAY_LABELS[dayIndex]} ${range}`);
	}
	if (parts.length === 0) return '';
	return `${label}: ${parts.join('; ')}.`;
}

// The block the agent reads from. Returns '' when nothing is configured.
function renderHoursSpoken(hours, departmentHours, timeZone, nowMs) {
	const lines = [];
	const storeLine = hoursWeekLine('Dealership', hours);
	if (storeLine) lines.push(storeLine);
	const deptLabels = { service: 'Service department', parts: 'Parts department', sales: 'Sales department', body_shop: 'Body shop' };
	for (const [key, label] of Object.entries(deptLabels)) {
		const line = hoursWeekLine(label, departmentHours && departmentHours[key]);
		if (line) lines.push(line);
	}
	if (lines.length === 0) return '';
	// Today/tomorrow anchors in the dealer's timezone — the audit's dominant
	// failure was the right department read on the wrong day.
	try {
		const dayName = (ms) => new Intl.DateTimeFormat('en-US', { timeZone, weekday: 'long' }).format(new Date(ms));
		const dateLabel = (ms) => new Intl.DateTimeFormat('en-US', { timeZone, weekday: 'long', month: 'long', day: 'numeric' }).format(new Date(ms));
		const anchor = (ms, word) => {
			const idx = HOURS_DAY_LABELS.indexOf(dayName(ms));
			if (idx < 0) return '';
			const store = hoursRangeForDay(hours, idx) || 'not listed';
			const service = hoursRangeForDay(departmentHours && departmentHours.service, idx) || 'not listed';
			return `${word} (${dateLabel(ms)}): dealership ${store}; service department ${service}.`;
		};
		const today = anchor(nowMs, 'Today');
		const tomorrow = anchor(nowMs + 86400000, 'Tomorrow');
		if (today) lines.push(today);
		if (tomorrow) lines.push(tomorrow);
	} catch {
		// Bad/missing timezone: the week block still stands on its own.
	}
	return lines.join('\n');
}
// ----- end TICKET-66 spoken hours ------------------------------------------


// ----- TICKET-149: transfer department lookup, format-insensitive ------------
// Config authors write the department keys as ".service", ".Service",
// "Service Department", "Parts Dept" and so on; an exact lowercase key match
// silently dropped every variant and the transfer failed. Keys are canonicalized
// to bare letters and looked up by department word; values may be plain number
// strings or {type, to} objects.
function transferNumberFor(transfers, name) {
	const dept = (transfers && transfers.department) || {};
	const toNumber = (value) => {
		if (typeof value === 'string') return value.trim();
		if (value && typeof value === 'object') return String(value.to || value.number || '').trim();
		return '';
	};
	const want = String(name).toLowerCase();
	let fallback = '';
	for (const [key, value] of Object.entries(dept)) {
		const canon = String(key).toLowerCase().replace(/[^a-z]/g, '');
		if (canon === want || canon === `${want}department` || canon === `${want}dept`) {
			const num = toNumber(value);
			if (num) return num;
		}
		if (!fallback && canon.startsWith(want)) fallback = toNumber(value);
	}
	return fallback;
}
// ----- end TICKET-149 --------------------------------------------------------

export default {
	async fetch(request, env, ctx) {
		// Hoisted above the try so the catch can still echo the payload that
		// caused the throw, whatever config had been resolved before it, and
		// every call already recorded.
		let payload = null;
		let debugConfig = null;
		const httpLog = DEBUG_ENABLED ? [] : null;

		const buildDebug = () => ({
			node_request: nodeRequest(payload),
			config: debugConfig,
			http_call_count: Array.isArray(httpLog) ? httpLog.length : 0,
			http_calls: httpLog,
		});

		try {
			payload = await request.json();

			const BASE_URL = 'https://config.api.example-provider.com/v1/dealer';

			const dealerSlug = String(payload?.dealerStub).trim();

			const configUrl = `${BASE_URL}/${encodeURIComponent(dealerSlug)}`;

			const configHeaders = { 'Content-Type': 'application/json' };
			const configBody = JSON.stringify({
				from: payload?.from || '',
				callId: payload?.callId || payload?.callID || '',
			});

			const configRecord = startCall(
				httpLog,
				'dealer_config',
				'POST',
				configUrl,
				configHeaders,
				configBody
			);
			const configStartedAt = Date.now();

			let configResponse;
			try {
				configResponse = await fetch(configUrl, {
					method: 'POST',
					headers: configHeaders,
					body: configBody,
				});
			} catch (configError) {
				// Rethrown untouched - the outer catch still owns the response
				// shape. This only completes the record, so a call that never came
				// back reads as attempted rather than missing.
				failCall(configRecord, configStartedAt, configError, false);
				throw configError;
			}

			finishCall(configRecord, configStartedAt, configResponse, null);

			const dealerConfig = configResponse.ok ? await configResponse.json() : {};

			// This response body is the credential store: for any dealer with
			// scheduling it carries the xTime Authorization and x-api-key verbatim
			// under apiData.ServiceScheduling.headers, whether or not this node
			// reads them. So a successful fetch is recorded as a size and never as
			// content, which still tells a real config apart from the empty 200 a
			// wrong dealerStub returns. A non-2xx body is an error page with no
			// credentials in it, and it is the case worth reading, so that one is
			// recorded whole.
			if (configRecord) {
				configRecord.response_body = configResponse.ok
					? `(omitted - ${JSON.stringify(dealerConfig ?? null)?.length ?? 0} chars of dealer config; it carries credentials)`
					: debugBody(await configResponse.text().catch(() => null));
			}

			const labels = {
				credit_card: 'credit card',
				personal_check: 'personal check',
				apple_pay: 'Apple Pay',
				google_pay: 'Google Pay',
				wifi: 'Wi-Fi',
			};

			const humanize = (value) => {
				const token = String(value || '');
				return labels[token] || token.replace(/_/g, ' ');
			};

			const spokenList = (items, conjunction = 'and') => {
				if (!Array.isArray(items) || items.length === 0) return '';
				const normalized = items.map(humanize).filter(Boolean);
				if (normalized.length === 0) return '';
				if (normalized.length === 1) return normalized[0];
				return `${normalized.slice(0, -1).join(', ')}, ${conjunction} ${
					normalized[normalized.length - 1]
				}`;
			};

			// ----- phone helpers -----
			const norm = (p) => (p || '').toString().replace(/\D/g, '').slice(-10);

			// ----- config-derived spoken variables -----
			const greeting = String(dealerConfig?.agent?.greeting_script || '')
				.replace(
					/\{\{dealership_name\}\}/g,
					dealerConfig?.campaign?.dealership_name || ''
				)
				.replace(/\{\{agent_name\}\}/g, dealerConfig?.agent?.name || '');

			// ----- middleware credentials -----
			const middlewareBaseUrl = 'https://dms.api.example-provider.com/api';
			const middlewareApiKey = 'mwk_EXAMPLE_REPLACE_ME';
			const dealerCode = dealerConfig?.apiData?.dealerCode || '';

			const phoneForLookup = norm(payload?.short_from || payload?.from);
			const phoneE164 = phoneForLookup ? `+1${phoneForLookup}` : '';

			// Assigned to the hoisted binding, so a throw further down - a dealer
			// config time_zone that Intl rejects, say - still reports what had been
			// resolved by then. The API key is a fingerprint here and nowhere near
			// the literal, even though the wiring below re-exports the value.
			debugConfig = {
				dealer_stub_raw: JSON.stringify(payload?.dealerStub ?? null),
				dealer_stub_used: dealerSlug,
				dealer_config_base_url: BASE_URL,
				middleware_base_url: middlewareBaseUrl,
				middleware_api_key: fingerprintKey(middlewareApiKey),
				dealer_code: dealerCode,
				phone_for_lookup: phoneForLookup,
				payload_keys: Object.keys(payload || {}).sort().join(', '),
			};

			// ----- customer lookup (parity with xTime pathway) -----
			let customerLookup = {
				found: false,
				matchCount: 0,
				searchedPhone: phoneForLookup,
				customer: null,
			};

			if (phoneE164 && dealerSlug) {
				// Declared outside the try so the catch below can complete the
				// record of a call that threw.
				let lookupRecord = null;
				let lookupStartedAt = 0;

				try {
					const lookupUrl = `${middlewareBaseUrl}/crm/lookup/${encodeURIComponent(dealerSlug)}`;
					const lookupHeaders = {
						'Content-Type': 'application/json',
						Accept: 'application/json',
						'x-api-key': middlewareApiKey,
					};
					const lookupBody = JSON.stringify({ phoneNumber: phoneE164 });

					lookupRecord = startCall(
						httpLog,
						'middleware_crm',
						'POST',
						lookupUrl,
						lookupHeaders,
						lookupBody
					);
					lookupStartedAt = Date.now();

					const customerResponse = await fetch(lookupUrl, {
						method: 'POST',
						headers: lookupHeaders,
						body: lookupBody,
					});

					finishCall(lookupRecord, lookupStartedAt, customerResponse, null);

					if (customerResponse.ok) {
						const body = await customerResponse.json();

						if (lookupRecord) {
							lookupRecord.response_body = debugBody(JSON.stringify(body ?? null));
						}

						const c = body?.customer || null;

						if (c) {
							customerLookup = {
								found: true,
								matchCount: 1,
								searchedPhone: phoneForLookup,
								appointments: body.activeAppointments || 'No Appointments',
								customer: {
									customerId: c.customerId || null,
									firstName: c.firstName || null,
									lastName: c.lastName || null,
									phone: c.phoneNumber || null,
									email: c.emailAddress || null,
									vehicles: body.vehicles || [],
									vehicleCount: (body.vehicles || []).length,
									appointments: body.activeAppointments || [],
								},
							};
						}
					} else {
						if (lookupRecord) {
							lookupRecord.response_body = debugBody(
								await customerResponse.text().catch(() => null)
							);
						}

						customerLookup.lookupError = `Middleware CRM lookup returned ${customerResponse.status}`;
					}
				} catch (lookupError) {
					// finishCall may already have stamped a status: anything that
					// throws after that is the JSON parse rather than the request,
					// so the status it recorded is kept instead of zeroed.
					if (lookupRecord?.status === undefined) {
						failCall(lookupRecord, lookupStartedAt, lookupError, false);
					} else {
						lookupRecord.error = lookupError?.message || String(lookupError);
					}

					customerLookup.lookupError = lookupError?.message || String(lookupError);
				}
			}

			// ----- dealer-local time -----
			const dealerTz = dealerConfig?.options?.time_zone;
			const utcNow = new Date();
			const nowDealership = new Intl.DateTimeFormat('en-US', {
				timeZone: dealerTz,
				weekday: 'long',
				year: 'numeric',
				month: 'long',
				day: 'numeric',
				hour: 'numeric',
				minute: '2-digit',
				hour12: true,
			}).format(utcNow);

			// ----- earliest bookable start date (now + dealer min lead time) -----
			// Availability searches must never start before the dealership's
			// configured minimum lead time. Compute it here (server-side, timezone
			// aware) instead of asking the agent to do date math: current time plus
			// min_appointment_lead_time_hours, expressed as a YYYY-MM-DD date in the
			// dealer's local timezone. en-CA formats as YYYY-MM-DD.
			const minLeadHours =
				Number(dealerConfig?.options?.min_appointment_lead_time_hours) || 0;
			const earliestStart = new Date(
				utcNow.getTime() + minLeadHours * 60 * 60 * 1000
			);
			const earliestStartDate = new Intl.DateTimeFormat('en-CA', {
				timeZone: dealerTz,
				year: 'numeric',
				month: '2-digit',
				day: '2-digit',
			}).format(earliestStart);

			// ----- next seven days (dealer-local) -----
			const nextSevenDaysFormatter = new Intl.DateTimeFormat('en-US', {
				timeZone: dealerTz,
				weekday: 'long',
				month: 'long',
				day: 'numeric',
			});

			const nextSevenDays = [];
			for (let i = 0; i < 7; i++) {
				const date = new Date(utcNow.getTime() + i * 24 * 60 * 60 * 1000);
				const parts = Object.fromEntries(
					nextSevenDaysFormatter
						.formatToParts(date)
						.map((p) => [p.type, p.value])
				);
				nextSevenDays.push(`${parts.month} ${parts.day}, ${parts.weekday}`);
			}
			const serviceNames = Array.isArray(dealerConfig?.services)
				? dealerConfig.services
						.map((service) => service?.name)
						.filter(Boolean)
						.join(', ')
				: '';
			return Response.json({
				config_loaded:
					configResponse.ok &&
					dealerConfig &&
					typeof dealerConfig === 'object' &&
					Object.keys(dealerConfig).length > 0,
				now: nowDealership,
				next_seven_days: nextSevenDays,
				// Earliest date availability may be searched/booked: now + the
				// dealer's min_appointment_lead_time_hours, as YYYY-MM-DD (dealer tz).
				earliest_start_date: earliestStartDate,
				greeting,
				agent_name: dealerConfig?.agent?.name || '',
				dealer_name: dealerConfig?.campaign?.dealership_name || '',
				dealer_address: dealerConfig?.address?.conversational || '',

				// dealership hours and department hours
				hours: JSON.stringify(dealerConfig?.hours || {}),
				hours_spoken: renderHoursSpoken(dealerConfig?.hours, dealerConfig?.department_hours, dealerTz, Date.now()),
				department_hours: JSON.stringify(dealerConfig?.department_hours || {}),

				payment_methods_spoken: spokenList(dealerConfig?.payment_methods, 'or'),
				amenities_spoken: spokenList(dealerConfig?.waiting_lounge_amenities),
				transportation_offered: Array.isArray(
					dealerConfig?.transportation_offered
				)
					? dealerConfig.transportation_offered.join(', ')
					: '',

				// Languages the dealership supports, as BCP-47 tags (e.g. en-US).
				supported_languages: Array.isArray(dealerConfig?.supported_languages)
					? dealerConfig.supported_languages
					: [],

				night_drop_script: dealerConfig?.agent?.night_drop_script || '',
				transfer_hold_message: dealerConfig?.agent?.transfer_hold_message || '',
				after_hours_policy: dealerConfig?.agent?.after_hours_policy || '',

				night_drop_enabled: Boolean(dealerConfig?.options?.night_drop),
				accepts_walk_ins: Boolean(dealerConfig?.options?.accepts_walk_ins),
				transfer_confirmation_required: Boolean(
					dealerConfig?.options?.transfer_confirmation_required
				),
				availability_window_days:
					dealerConfig?.options?.availability_search_window_days || '0',
				min_lead_time_hours:
					dealerConfig?.options?.min_appointment_lead_time_hours || '0',
				recall_min_lead_days:
					dealerConfig?.options?.recall_min_lead_time_days || '0',
				can_quote_warranty: Boolean(
					dealerConfig?.options?.agent_can_quote_warranty
				),
				can_promise_ready_time: Boolean(
					dealerConfig?.options?.agent_can_promise_ready_time
				),
				max_retry_attempts:
					dealerConfig?.options?.max_function_retry_attempts || '0',
				speak_numbers_as_words: Boolean(
					dealerConfig?.options?.speak_numbers_as_words
				),
				time_zone: dealerConfig?.options?.time_zone || '',
				// transfers
				transfers_json: JSON.stringify(dealerConfig?.transfers || {}),
				transfer_service: transferNumberFor(dealerConfig?.transfers, 'service'),
				transfer_parts: transferNumberFor(dealerConfig?.transfers, 'parts'),
				transfer_sales: transferNumberFor(dealerConfig?.transfers, 'sales'),
				transfer_escalation: transferNumberFor(dealerConfig?.transfers, 'escalation'),

				dealer_code: dealerCode,
				dealership_id: dealerConfig?.campaign?.dealership_id || '',

				middleware_base_url: middlewareBaseUrl,
				middleware_api_key: middlewareApiKey,
				dealerStub: dealerSlug,

				active_phone: phoneForLookup,
				active_phone_e164: phoneE164,

				email: '',

				services_config: JSON.stringify(dealerConfig?.services || []),
				// Prompt-sized view for the Pricing Details node (see slimPricingConfig).
				services_pricing_config: JSON.stringify(slimPricingConfig(dealerConfig?.services || [])),
				service_names: serviceNames,

				// ----- customer profile (parity with xTime) -----
				cust_found: customerLookup.found,
				match_count: customerLookup.matchCount,
				searched_phone: customerLookup.searchedPhone,
				appointments: customerLookup.appointments,
				customer: customerLookup.customer,
				...(customerLookup.lookupError
					? { customer_lookup_error: customerLookup.lookupError }
					: {}),

				// The pathway-wide debug switch, exported so every downstream
				// snippet gates its own debug output on this one flag.
				debug_enabled: DEBUG_ENABLED,
				...(DEBUG_ENABLED ? { debug: buildDebug() } : {}),
			});
		} catch (error) {
			return Response.json(
				{
					config_loaded: false,
					error: 'Failed to load dealer configuration.',
					message: error?.message || String(error),
					debug_enabled: DEBUG_ENABLED,
					...(DEBUG_ENABLED ? { debug: buildDebug() } : {}),
				},
				{ status: 400 }
			);
		}
	},
};
