// ---------------------------------------------------------------------------
// services_pricing_config (from a live incident)
//
// The Pricing Details node inlines a services config into its prompt, and a
// big store's full catalog (opcodes, routing groups, kilobyte notes) put that
// node ~100KB over the model input limit live (a large multi-brand store, observed live).
// This produces a prompt-sized view: pricing-relevant fields only, notes
// capped, whole thing budgeted. The FULL services_config variable is
// untouched — the service resolver still gets everything.
//
// Degrades progressively under the budget: full notes -> short notes -> no
// notes -> tail truncation with an advisor marker. Names and prices are the
// last thing standing, because a wrong "we don't have that" costs more than
// a missing description.
// ---------------------------------------------------------------------------

const PRICING_CONFIG_MAX_CHARS = 30000;
const PRICING_NOTE_MAX_CHARS = 400;

export function slimPricingConfig(services) {
	let list = services;

	if (typeof list === 'string') {
		try {
			list = JSON.parse(list);
		} catch {
			list = [];
		}
	}

	if (!Array.isArray(list)) {
		return [];
	}

	const slimEntry = (service, noteCap) => {
		const entry = { name: String(service.name ?? '') };

		if (service.price !== undefined && service.price !== null && service.price !== '') {
			entry.price = service.price;
		}

		if (service.wait !== undefined && service.wait !== null && service.wait !== '') {
			entry.wait = service.wait;
		}

		if (noteCap > 0 && service.notes) {
			const notes = String(service.notes);

			entry.notes = notes.length > noteCap ? `${notes.slice(0, noteCap)}…` : notes;
		}

		if (service.walk_in_allowed !== undefined) {
			entry.walk_in_allowed = service.walk_in_allowed;
		}

		if (service.unsupported !== undefined) {
			entry.unsupported = service.unsupported;
		}

		return entry;
	};

	const real = list.filter((service) => service && typeof service === 'object');

	for (const noteCap of [PRICING_NOTE_MAX_CHARS, 120, 0]) {
		const slimmed = real.map((service) => slimEntry(service, noteCap));

		if (JSON.stringify(slimmed).length <= PRICING_CONFIG_MAX_CHARS) {
			return slimmed;
		}
	}

	// Notes are already gone and it still doesn't fit: keep as many entries as
	// the budget allows and say so, instead of silently pretending the rest of
	// the catalog doesn't exist.
	const bare = real.map((service) => slimEntry(service, 0));
	const kept = [];
	let used = 2; // the array brackets

	for (const entry of bare) {
		const chars = JSON.stringify(entry).length + 1;

		if (used + chars > PRICING_CONFIG_MAX_CHARS - 200) {
			break;
		}

		kept.push(entry);
		used += chars;
	}

	const dropped = bare.length - kept.length;

	if (dropped > 0) {
		kept.push({ name: `…and ${dropped} more services — the service advisor can price anything not listed here` });
	}

	return kept;
}

